mapper.select:
SELECT t.sales_date AS salesDate, a.area_name AS areaName, b.branch_name AS branchName, t.budget_amount AS budgetAmount, t.actual_amount AS actualAmount FROM t_daily_sales t INNER JOIN m_branch b ON t.branch_code = b.branch_code INNER JOIN m_area a ON b.area_code = a.area_code
AND t.sales_date >= #{startDate}
AND t.sales_date <= #{endDate}
ORDER BY
t.sales_date ASC, a.area_code ASC, b.branch_code ASC
t.sales_date DESC, a.area_code ASC, b.branch_code ASC

SELECT b.branch_name AS branchName, a.area_name AS areaName, SUM(t.budget_amount) AS totalBudget, SUM(t.actual_amount) AS totalActual FROM t_daily_sales t INNER JOIN m_branch b ON t.branch_code = b.branch_code INNER JOIN m_area a ON b.area_code = a.area_code
AND t.sales_date >= #{startDate} AND t.sales_date <= #{endDate}
GROUP BY b.branch_code, b.branch_name, a.area_code, a.area_name ORDER BY b.branch_code
